using System;using System.IO;using System.Linq;using System.Reflection;using UnityEditor;using UnityEngine;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public static class StudioHierarchyOrderValidation {
 static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;static StudioModelEditor editor;static StudioModelDocument doc;static OrderWindow window;static int checks,stage;static double next;static string error;static Vector2 guide;
 static string PathFor(string n)=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../"+n));static void Check(bool ok,string m){if(!ok)throw new Exception(m);checks++;}static void Near(Matrix4x4 a,Matrix4x4 b){for(int i=0;i<16;i++)Check(Mathf.Abs(a[i]-b[i])<.001f,"World placement changed");}static void Order(int parent,params int[] expected)=>Check(doc.OrderedChildren(parent).SequenceEqual(expected),"Wrong sibling order under "+parent);
 public static void Run(){EditorApplication.delayCall+=Start;}
 static void Start(){try{doc=ScriptableObject.CreateInstance<StudioModelDocument>();doc.nodes.Add(new StudioModelDocument.Node{name="Parent A",position=new Vector3(1,2,3),rotation=Quaternion.Euler(0,30,0),scale=Vector3.one*2});doc.nodes.Add(new StudioModelDocument.Node{name="Parent B",position=new Vector3(-4,1,0)});doc.nodes.Add(new StudioModelDocument.Node{name="Parent C"});doc.nodes.Add(new StudioModelDocument.Node{name="Child",parent=0,position=new Vector3(2,.5f,1),positionOffset=new Vector3(.1f,0,0),rotation=Quaternion.Euler(25,0,0)});doc.nodes.Add(new StudioModelDocument.Node{name="Leaf",parent=3,position=Vector3.forward});doc.nodes.Add(new StudioModelDocument.Node{name="Other child",parent=0});editor=new StudioModelEditor(()=>window?.Repaint());editor.Load(doc);editor.SelectObject(0);var nodes=doc.nodes.ToArray();var instances=editor.Transforms;var worlds=instances.Select(t=>t.localToWorldMatrix).ToArray();Order(-1,0,1,2);Order(0,3,5);editor.PlaceHierarchy(new[]{5,3},0,3);Order(0,5,3);editor.PlaceHierarchy(new[]{3,4},1,-1);Check(doc.nodes[3].parent==1&&doc.nodes[4].parent==3,"Selected descendants moved twice");Order(1,3);editor.PlaceHierarchy(new[]{2},-1,0);Order(-1,2,0,1);editor.PlaceHierarchy(new[]{4},-1,1);Order(-1,2,0,4,1);Check(doc.nodes[4].parent==-1,"Leaf did not unparent");Check(ReferenceEquals(instances,editor.Transforms)&&nodes.Zip(doc.nodes,(a,b)=>ReferenceEquals(a,b)).All(v=>v),"Move rebuilt instances or reindexed nodes");for(int i=0;i<worlds.Length;i++)Near(worlds[i],editor.Transforms[i].localToWorldMatrix);editor.PerformWorkspaceHistory(false);Order(-1,2,0,1);Check(doc.nodes[4].parent==3,"Undo failed to restore parent");editor.PerformWorkspaceHistory(true);Order(-1,2,0,4,1);Check(doc.nodes[4].parent==-1,"Redo failed to restore unparent");Check(!doc.CanPlaceHierarchy(new[]{1},3,-1,editor.Transforms,out _),"Cycle accepted");Check(!doc.CanPlaceHierarchy(new[]{2},1,0,editor.Transforms,out _),"Foreign insertion sibling accepted");Check(!doc.CanPlaceHierarchy(new[]{2},-1,0,editor.Transforms,out _),"No-op accepted");var filename=StudioModelDocument.NewWorkspacePath("Hierarchy order roundtrip");StudioWorkspaceText.Write(doc,filename);var read=StudioWorkspaceText.Read(filename);Check(read.OrderedHierarchy().SequenceEqual(doc.OrderedHierarchy()),"Portable workspace loses order");Check(read.nodes.Select(n=>n.siblingOrder).SequenceEqual(doc.nodes.Select(n=>n.siblingOrder)),"Sibling metadata not saved");Object.DestroyImmediate(read);var middle=editor.ResolveHierarchyDrop(new Rect(62,100,280,20),3,new Vector2(150,110));Check(!middle.Insert&&middle.Parent==3,"Row center must parent");var before=editor.ResolveHierarchyDrop(new Rect(62,100,280,20),3,new Vector2(100,100.5f));Check(before.Insert&&before.Parent==1&&before.Before==3,"Top row gap must insert sibling");var outdent=editor.ResolveHierarchyDrop(new Rect(62,100,280,20),3,new Vector2(51,100.5f));Check(outdent.Insert&&outdent.Parent==-1&&outdent.Before==-1&&outdent.Line.x<before.Line.x,"Leftward gap must outdent after ancestor");var leaf=editor.ResolveHierarchyDrop(new Rect(62,100,280,20),5,new Vector2(150,119));Check(leaf.Insert&&leaf.Parent==0,"After leaf should not create a child");var first=editor.ResolveHierarchyDrop(new Rect(50,100,290,20),0,new Vector2(90,119));Check(first.Insert&&first.Parent==0&&first.Before==5,"Indented parent gap must insert first child");var rootAfter=editor.ResolveHierarchyDrop(new Rect(50,100,290,20),2,new Vector2(150,119));Check(rootAfter.Parent==-1&&rootAfter.Before==0,"After root leaf must insert root sibling");var deep=ScriptableObject.CreateInstance<StudioModelDocument>();for(int d=0;d<12;d++)deep.nodes.Add(new StudioModelDocument.Node{name="Depth "+d,parent=d-1});using(var deepEditor=new StudioModelEditor(()=>{})){deepEditor.Load(deep);var deepRow=new Rect(146,100,200,20);var same=deepEditor.ResolveHierarchyDrop(deepRow,10,new Vector2(160,100.5f));Check(same.Parent==9,"Deep insertion retains sibling depth");var one=deepEditor.ResolveHierarchyDrop(deepRow,10,new Vector2(134,100.5f));Check(one.Parent==8,"Deep leftward drag outdents one level");}Object.DestroyImmediate(deep);StudioSettings.Current.theme="graphite";Seed();window=ScriptableObject.CreateInstance<OrderWindow>();window.ShowUtility();window.position=new Rect(80,80,390,270);next=EditorApplication.timeSinceStartup+1;EditorApplication.update+=Tick;}catch(Exception e){Finish(e.ToString());}}
 static void Seed(){var type=typeof(StudioModelEditor).GetNestedType("HierarchyDragPayload",BindingFlags.NonPublic);var payload=Activator.CreateInstance(type,true);foreach(var pair in new[]{new object[]{"owner",editor},new object[]{"document",doc},new object[]{"selection",new[]{1}},new object[]{"nodes",new[]{doc.nodes[1]}}})type.GetField((string)pair[0],F|BindingFlags.Public).SetValue(payload,pair[1]);DragAndDrop.SetGenericData("MashBoxStudio.HierarchyDrag",payload);}
 static void Tick(){if(EditorApplication.timeSinceStartup<next)return;next=EditorApplication.timeSinceStartup+.4;try{if(error!=null)throw new Exception(error);Seed();window.SendEvent(new Event{type=EventType.Layout});window.SendEvent(new Event{type=EventType.Repaint});if(++stage==3){Finish("PASS "+checks+" hierarchy ordering/placement/render checks");return;}window.Repaint();}catch(Exception e){Finish(e.ToString());}}
 public sealed class OrderWindow:EditorWindow{
 void OnGUI(){if(editor==null||Event.current.type!=EventType.Repaint)return;var rt=new RenderTexture(390,270,0);rt.Create();var old=RenderTexture.active;var pointer=Event.current.mousePosition;GL.PushMatrix();try{RenderTexture.active=rt;GL.Clear(false,true,Color.clear);GL.LoadPixelMatrix(0,390,270,0);using(StudioTheme.Scope()){EditorGUI.DrawRect(new Rect(0,0,390,270),StudioTheme.Current.Panel);var rows=doc.OrderedHierarchy();int target=stage==1?5:0;int targetAt=Array.IndexOf(rows,target);int depth=0;for(int p=doc.nodes[target].parent;p>=0;p=doc.nodes[p].parent)depth++;var targetRect=new Rect(40+depth*12,40+targetAt*22,300-depth*12,20);var point=stage==0?new Vector2(140,targetRect.y+.5f):stage==1?new Vector2(41,targetRect.y+.5f):new Vector2(140,targetRect.center.y);Event.current.mousePosition=point;var placement=editor.ResolveHierarchyDrop(targetRect,target,point);guide=placement.Line;for(int n=0;n<rows.Length;n++){int i=rows[n],d=0;for(int p=doc.nodes[i].parent;p>=0;p=doc.nodes[p].parent)d++;typeof(StudioModelEditor).GetMethod("DrawHierarchyDragRow",F).Invoke(editor,new object[]{new Rect(40+d*12,40+n*22,300-d*12,20),new GUIContent(doc.nodes[i].name),StudioTheme.Styles.hierarchyRow,i});}}var image=new Texture2D(390,270,TextureFormat.RGBA32,false);image.ReadPixels(new Rect(0,0,390,270),0,0);image.Apply();if(stage<2&&guide.y>0){var line=image.GetPixel(200,269-(int)guide.y);var back=image.GetPixel(200,269-(int)guide.y-5);Check(Mathf.Abs(line.r-back.r)+Mathf.Abs(line.g-back.g)+Mathf.Abs(line.b-back.b)>.05f,"Native insertion line not rendered");}File.WriteAllBytes(PathFor("hierarchy-insert-"+stage+".png"),image.EncodeToPNG());Object.DestroyImmediate(image);}catch(Exception e){error=e.ToString();}finally{Event.current.mousePosition=pointer;GL.PopMatrix();RenderTexture.active=old;Object.DestroyImmediate(rt);}}
 }
 static void Finish(string result){EditorApplication.update-=Tick;DragAndDrop.SetGenericData("MashBoxStudio.HierarchyDrag",null);File.WriteAllText(PathFor("hierarchy-order-result.txt"),result);EditorApplication.delayCall+=()=>EditorApplication.Exit(result.StartsWith("PASS")?0:1);}
}
